import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

type Rect = { left: number; right: number; top: number } | null;

// Прямоугольник текстового узла (Range.getBoundingClientRect); при наличии `within` — внутри блока с этим текстом.
async function textRect(page: Page, text: string, within?: string): Promise<Rect> {
  return page.evaluate(
    ({ text, within }) => {
      let root: Node = document.body;
      if (within) {
        const w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
        let n: Node | null;
        while ((n = w.nextNode())) {
          if (n.textContent?.trim() === within) {
            root = n.parentElement?.parentElement?.parentElement ?? document.body;
            break;
          }
        }
      }
      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
      let node: Node | null;
      while ((node = walker.nextNode())) {
        if (node.textContent?.trim() === text) {
          const range = document.createRange();
          range.selectNodeContents(node);
          const r = range.getBoundingClientRect();
          return { left: r.left, right: r.right, top: r.top };
        }
      }
      return null;
    },
    { text, within },
  );
}

const TOL = 6;

// Прямоугольник текста элемента (Range по содержимому) — как textRect, но внутри конкретного локатора.
async function rangeRect(locator: import('@playwright/test').Locator): Promise<Rect> {
  return locator.evaluate((el) => {
    const range = document.createRange();
    range.selectNodeContents(el);
    const r = range.getBoundingClientRect();
    return { left: r.left, right: r.right, top: r.top };
  });
}

// Дождаться окончания загрузки данных и стабилизации раскладки: строк «טוענים …» нет,
// а координаты регионов/кнопок/прогресса совпадают в двух замерах подряд.
async function waitForStableLayout(page: Page) {
  await expect(page.getByText(/^טוענים .*…$/)).toHaveCount(0, { timeout: 30_000 }).catch(() => {});
  let prev = '';
  await expect
    .poll(
      async () => {
        const sig = await page.evaluate(() =>
          JSON.stringify([
            document.documentElement.scrollHeight,
            ...Array.from(document.querySelectorAll('[role="region"], [role="button"], [role="progressbar"], [role="heading"]')).map((e) => {
              const r = e.getBoundingClientRect();
              return [Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height)];
            }),
          ]),
        );
        const same = sig === prev;
        prev = sig;
        return same;
      },
      { timeout: 15_000, intervals: [300] },
    )
    .toBe(true);
}

test.describe('«המסע שלי»', () => {
  test('JR-03 RTL-раскладка «המסע שלי» по координатам #6a86f7df @prod-safe @mobile', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. До перехода: подмена prayer_completions до 15 записей (как в JR-01), чтобы была строка «N תפילות לדרגה הבאה».
    await page.route('**/rest/v1/prayer_completions**', async (route) => {
      if (route.request().method() !== 'GET') {
        await route.continue();
        return;
      }
      const response = await route.fetch();
      let json: unknown;
      try {
        json = await response.json();
      } catch {
        await route.fulfill({ response });
        return;
      }
      await route.fulfill({ response, json: Array.isArray(json) ? json.slice(0, 15) : json });
    });

    // 2. Открыть `/journey`; измерить Range.getBoundingClientRect текстов и иконки-стрелки.
    await page.goto('/journey');
    await expect(page.getByText('5 תפילות לדרגה הבאה')).toBeVisible({ timeout: 20_000 });
    await expect(page.getByRole('region', { name: /^ערבית: \d+$/ })).toBeVisible({ timeout: 20_000 });
    await dismissMilestoneIfShown(page);
    await waitForStableLayout(page);

    // «מקבל על עצמי»: заголовок и текст справа (right ≈ 350), стрелка-svg слева (x ≈ 38–50)
    const commitCard = page.getByRole('button', { name: /^מקבל על עצמי/ });
    const commitTitle = await rangeRect(commitCard.getByText('מקבל על עצמי', { exact: true }).first());
    expect(commitTitle).not.toBeNull();
    expect(Math.abs(commitTitle!.right - 350)).toBeLessThanOrEqual(TOL);
    const arrow = await page.getByRole('button', { name: /^מקבל על עצמי/ }).locator('svg').first().boundingBox();
    expect(arrow).not.toBeNull();
    expect(arrow!.x).toBeGreaterThanOrEqual(38 - TOL);
    expect(arrow!.x + arrow!.width).toBeLessThanOrEqual(50 + TOL);

    // «פילוח תפילות»: названия справа (right ≈ 286), числа слева (left ≈ 60)
    for (const name of ['שחרית', 'מנחה', 'ערבית']) {
      const region = page.getByRole('region', { name: new RegExp(`^${name}: \\d+$`) });
      // Название ищется внутри своего региона: то же слово (напр. «מנחה») есть и в шапке «זמני התפילות של היום».
      const label = await rangeRect(region.getByText(name, { exact: true }).first());
      expect(label).not.toBeNull();
      expect(Math.abs(label!.right - 286)).toBeLessThanOrEqual(TOL);
      const value = (await region.getAttribute('aria-label'))!.split(': ')[1];
      const num = await region.getByText(value, { exact: true }).last().evaluate((el) => {
        const range = document.createRange();
        range.selectNodeContents(el);
        return range.getBoundingClientRect().left;
      });
      expect(Math.abs(num - 60)).toBeLessThanOrEqual(TOL);
    }

    // Прогресс: «5 תפילות לדרגה הבאה» справа (right ≈ 366), «דרגה 2 מתוך 10» слева (left ≈ 24), одинаковый top
    const next = await textRect(page, '5 תפילות לדרגה הבאה');
    const level = await textRect(page, 'דרגה 2 מתוך 10');
    expect(next).not.toBeNull();
    expect(level).not.toBeNull();
    expect(Math.abs(next!.right - 366)).toBeLessThanOrEqual(TOL);
    expect(Math.abs(level!.left - 24)).toBeLessThanOrEqual(TOL);
    expect(Math.abs(next!.top - level!.top)).toBeLessThanOrEqual(2);
  });
});
